1	package server
2	
3	import (
4		"encoding/json"
5		"io"
6		"math"
7		"mime"
8		"net/http"
9		"sort"
10		"strings"
11		"time"
12	)
13	
14	const (
15		alertRulesPath   = "/api/v1/alert-rules"
16		alertRulesPrefix = alertRulesPath + "/"
17		alertsPath       = "/api/v1/alerts"
18	)
19	
20	// ruleSelector selects series by exact metric name and a subset of labels.
21	type ruleSelector struct {
22		metric string
23		labels map[string]string
24	}
25	
26	// alertRule is an immutable rule document. Replacements swap the pointer
27	// atomically, so readers never observe a half-updated rule.
28	type alertRule struct {
29		id        string
30		kind      string // "threshold" | "ratio"
31		operator  string // gt | gte | lt | lte
32		threshold float64
33	
34		// threshold rules use left only; ratio rules use both sides.
35		left  *ruleSelector
36		right *ruleSelector
37	}
38	
39	// ---- JSON wire shapes ------------------------------------------------------
40	
41	type ruleSideJSON struct {
42		Metric string            `json:"metric"`
43		Labels map[string]string `json:"labels"`
44	}
45	
46	type thresholdRuleJSON struct {
47		ID        string            `json:"id"`
48		Kind      string            `json:"kind"`
49		Operator  string            `json:"operator"`
50		Threshold float64           `json:"threshold"`
51		Metric    string            `json:"metric"`
52		Labels    map[string]string `json:"labels"`
53	}
54	
55	type ratioRuleJSON struct {
56		ID          string       `json:"id"`
57		Kind        string       `json:"kind"`
58		Operator    string       `json:"operator"`
59		Threshold   float64      `json:"threshold"`
60		Numerator   ruleSideJSON `json:"numerator"`
61		Denominator ruleSideJSON `json:"denominator"`
62	}
63	
64	func ruleWireJSON(r *alertRule) any {
65		if r.kind == "ratio" {
66			return ratioRuleJSON{
67				ID:          r.id,
68				Kind:        r.kind,
69				Operator:    r.operator,
70				Threshold:   r.threshold,
71				Numerator:   sideWireJSON(r.left),
72				Denominator: sideWireJSON(r.right),
73			}
74		}
75		return thresholdRuleJSON{
76			ID:        r.id,
77			Kind:      r.kind,
78			Operator:  r.operator,
79			Threshold: r.threshold,
80			Metric:    r.left.metric,
81			Labels:    copyLabels(r.left.labels),
82		}
83	}
84	
85	func sideWireJSON(s *ruleSelector) ruleSideJSON {
86		return ruleSideJSON{Metric: s.metric, Labels: copyLabels(s.labels)}
87	}
88	
89	// ---- request decoding ------------------------------------------------------
90	
91	type rawRuleSide struct {
92		Metric *string            `json:"metric"`
93		Labels *map[string]string `json:"labels"`
94	}
95	
96	type rawRule struct {
97		Kind        *string            `json:"kind"`
98		Operator    *string            `json:"operator"`
99		Threshold   *float64           `json:"threshold"`
100		Metric      *string            `json:"metric"`
101		Labels      *map[string]string `json:"labels"`
102		Numerator   *rawRuleSide       `json:"numerator"`
103		Denominator *rawRuleSide       `json:"denominator"`
104	}
105	
106	// decodeRule parses and fully validates a rule body. It never returns a
107	// partially validated rule.
108	func decodeRule(body []byte) (*alertRule, bool) {
109		var raw rawRule
110		if !strictDecode(body, &raw) {
111			return nil, false
112		}
113		if raw.Kind == nil || raw.Operator == nil || raw.Threshold == nil {
114			return nil, false
115		}
116		kind := *raw.Kind
117		if kind != "threshold" && kind != "ratio" {
118			return nil, false
119		}
120		operator := *raw.Operator
121		if !validOperators[operator] {
122			return nil, false
123		}
124		threshold := *raw.Threshold
125		if math.IsNaN(threshold) || math.IsInf(threshold, 0) {
126			return nil, false
127		}
128	
129		build := func() *alertRule {
130			return &alertRule{kind: kind, operator: operator, threshold: threshold}
131		}
132	
133		switch kind {
134		case "threshold":
135			if raw.Metric == nil || raw.Labels == nil || raw.Numerator != nil || raw.Denominator != nil {
136				return nil, false
137			}
138			sel, ok := decodeSelector(*raw.Metric, *raw.Labels)
139			if !ok {
140				return nil, false
141			}
142			r := build()
143			r.left = sel
144			return r, true
145		case "ratio":
146			if raw.Metric != nil || raw.Labels != nil || raw.Numerator == nil || raw.Denominator == nil {
147				return nil, false
148			}
149			num, ok := decodeRawSide(raw.Numerator)
150			if !ok {
151				return nil, false
152			}
153			den, ok := decodeRawSide(raw.Denominator)
154			if !ok {
155				return nil, false
156			}
157			r := build()
158			r.left, r.right = num, den
159			return r, true
160		}
161		return nil, false
162	}
163	
164	func decodeRawSide(raw *rawRuleSide) (*ruleSelector, bool) {
165		if raw.Metric == nil || raw.Labels == nil {
166			return nil, false
167		}
168		return decodeSelector(*raw.Metric, *raw.Labels)
169	}
170	
171	func decodeSelector(metric string, labels map[string]string) (*ruleSelector, bool) {
172		if !identPattern.MatchString(metric) || labels == nil {
173			return nil, false
174		}
175		for k := range labels {
176			if !identPattern.MatchString(k) {
177				return nil, false
178			}
179		}
180		return &ruleSelector{metric: metric, labels: copyLabels(labels)}, true
181	}
182	
183	var validOperators = map[string]bool{
184		"gt":  true,
185		"gte": true,
186		"lt":  true,
187		"lte": true,
188	}
189	
190	// ---- store operations ------------------------------------------------------
191	
192	func (s *metricStore) putRule(r *alertRule) bool {
193		s.mu.Lock()
194		defer s.mu.Unlock()
195		_, existed := s.rules[r.id]
196		s.rules[r.id] = r
197		return !existed
198	}
199	
200	func (s *metricStore) getRule(id string) (*alertRule, bool) {
201		s.mu.RLock()
202		defer s.mu.RUnlock()
203		r, ok := s.rules[id]
204		return r, ok
205	}
206	
207	func (s *metricStore) deleteRule(id string) bool {
208		s.mu.Lock()
209		defer s.mu.Unlock()
210		if _, ok := s.rules[id]; !ok {
211			return false
212		}
213		delete(s.rules, id)
214		return true
215	}
216	
217	// snapshotRules returns all rules sorted by id. Rule objects are immutable,
218	// so the pointers stay safe after the lock is released.
219	func (s *metricStore) snapshotRules() []*alertRule {
220		s.mu.RLock()
221		defer s.mu.RUnlock()
222		out := make([]*alertRule, 0, len(s.rules))
223		for _, r := range s.rules {
224			out = append(out, r)
225		}
226		sort.Slice(out, func(i, j int) bool { return out[i].id < out[j].id })
227		return out
228	}
229	
230	// selectorSum sums current values of all matching counter/gauge series.
231	// ok is false when no counter/gauge series matches; histograms are ignored,
232	// so a selector matching histograms only counts as unavailable.
233	func (s *metricStore) selectorSum(sel *ruleSelector) (sum float64, ok bool) {
234		for _, cur := range s.series {
235			if cur.typ != "counter" && cur.typ != "gauge" {
236				continue
237			}
238			if cur.name != sel.metric {
239				continue
240			}
241			matched := true
242			for k, v := range sel.labels {
243				got, exists := cur.labels[k]
244				if !exists || got != v {
245					matched = false
246					break
247				}
248			}
249			if !matched {
250				continue
251			}
252			sum += cur.value
253			ok = true
254		}
255		return sum, ok
256	}
257	
258	type alertOutput struct {
259		ID         string   `json:"id"`
260		State      string   `json:"state"`
261		Value      *float64 `json:"value"`
262		Silenced   bool     `json:"silenced"`
263		SilenceIDs []string `json:"silence_ids"`
264	}
265	
266	// evalAlerts computes every rule against a single consistent snapshot of
267	// metrics, rules and silences; results are sorted by rule id.
268	func (s *metricStore) evalAlerts() []alertOutput {
269		s.mu.RLock()
270		defer s.mu.RUnlock()
271	
272		rules := make([]*alertRule, 0, len(s.rules))
273		for _, r := range s.rules {
274			rules = append(rules, r)
275		}
276		sort.Slice(rules, func(i, j int) bool { return rules[i].id < rules[j].id })
277	
278		silences := make([]*silence, 0, len(s.silences))
279		for _, sil := range s.silences {
280			silences = append(silences, sil)
281		}
282		// Evaluation instant and silence windowing share the snapshot.
283		now := time.Now()
284		activeByRule := activeSilencesByRule(silences, now)
285	
286		out := make([]alertOutput, 0, len(rules))
287		for _, r := range rules {
288			al := alertOutput{ID: r.id, State: "inactive", SilenceIDs: []string{}}
289	
290			var value float64
291			if r.kind == "threshold" {
292				sum, ok := s.selectorSum(r.left)
293				if !ok {
294					al.State = "no_data"
295					out = append(out, al)
296					continue
297				}
298				value = sum
299			} else {
300				num, numOK := s.selectorSum(r.left)
301				den, denOK := s.selectorSum(r.right)
302				if !numOK || !denOK || den == 0 {
303					al.State = "no_data"
304					out = append(out, al)
305					continue
306				}
307				value = num / den
308			}
309	
310			v := value
311			al.Value = &v
312			if compareHolds(r.operator, value, r.threshold) {
313				al.State = "firing"
314				if hits := activeByRule[r.id]; len(hits) > 0 {
315					al.Silenced = true
316					al.SilenceIDs = append([]string(nil), hits...)
317				}
318			}
319			out = append(out, al)
320		}
321		return out
322	}
323	
324	func compareHolds(operator string, value, threshold float64) bool {
325		switch operator {
326		case "gt":
327			return value > threshold
328		case "gte":
329			return value >= threshold
330		case "lt":
331			return value < threshold
332		case "lte":
333			return value <= threshold
334		}
335		return false
336	}
337	
338	// ---- HTTP handlers ---------------------------------------------------------
339	
340	func registerAlertHandlers(mux *http.ServeMux, store *metricStore) {
341		mux.HandleFunc(alertRulesPath, func(w http.ResponseWriter, r *http.Request) {
342			if r.Method != http.MethodGet {
343				w.Header().Set("Allow", http.MethodGet)
344				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
345				return
346			}
347			rules := store.snapshotRules()
348			body := make([]any, 0, len(rules))
349			for _, rule := range rules {
350				body = append(body, ruleWireJSON(rule))
351			}
352			writeJSON(w, http.StatusOK, map[string]any{"rules": body})
353		})
354	
355		mux.HandleFunc(alertRulesPrefix, func(w http.ResponseWriter, r *http.Request) {
356			id := strings.TrimPrefix(r.URL.Path, alertRulesPrefix)
357			switch r.Method {
358			case http.MethodGet, http.MethodDelete:
359				// Reads and deletions can only address an existing, syntactically
360				// valid rule id; anything else is simply not found.
361				if id == "" || strings.Contains(id, "/") || !identPattern.MatchString(id) {
362					writeAPIError(w, "rule_not_found", http.StatusNotFound)
363					return
364				}
365				if r.Method == http.MethodGet {
366					handleRuleGet(w, id, store)
367				} else {
368					handleRuleDelete(w, id, store)
369				}
370			case http.MethodPut:
371				// A structurally nested path is outside this resource subtree;
372				// an identifier-shaped but invalid id is a bad rule identifier.
373				if id == "" || strings.Contains(id, "/") {
374					writeAPIError(w, "rule_not_found", http.StatusNotFound)
375					return
376				}
377				if !identPattern.MatchString(id) {
378					writeAPIError(w, "invalid_rule", http.StatusBadRequest)
379					return
380				}
381				handleRulePut(w, r, id, store)
382			default:
383				w.Header().Set("Allow", "GET, PUT, DELETE")
384				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
385			}
386		})
387	
388		mux.HandleFunc(alertsPath, func(w http.ResponseWriter, r *http.Request) {
389			if r.Method != http.MethodGet {
390				w.Header().Set("Allow", http.MethodGet)
391				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
392				return
393			}
394			writeJSON(w, http.StatusOK, map[string]any{"alerts": store.evalAlerts()})
395		})
396	}
397	
398	func handleRuleGet(w http.ResponseWriter, id string, store *metricStore) {
399		rule, ok := store.getRule(id)
400		if !ok {
401			writeAPIError(w, "rule_not_found", http.StatusNotFound)
402			return
403		}
404		writeJSON(w, http.StatusOK, ruleWireJSON(rule))
405	}
406	
407	func handleRulePut(w http.ResponseWriter, r *http.Request, id string, store *metricStore) {
408		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
409		if err != nil || mediaType != "application/json" {
410			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
411			return
412		}
413	
414		body, err := io.ReadAll(r.Body)
415		if err != nil {
416			writeAPIError(w, "invalid_rule", http.StatusBadRequest)
417			return
418		}
419	
420		rule, ok := decodeRule(body)
421		if !ok {
422			writeAPIError(w, "invalid_rule", http.StatusBadRequest)
423			return
424		}
425		rule.id = id
426	
427		created := store.putRule(rule)
428		status := http.StatusOK
429		if created {
430			status = http.StatusCreated
431		}
432		writeJSON(w, status, ruleWireJSON(rule))
433	}
434	
435	func handleRuleDelete(w http.ResponseWriter, id string, store *metricStore) {
436		if !store.deleteRule(id) {
437			writeAPIError(w, "rule_not_found", http.StatusNotFound)
438			return
439		}
440		w.WriteHeader(http.StatusNoContent)
441	}
442	
443	func writeJSON(w http.ResponseWriter, status int, payload any) {
444		w.Header().Set("Content-Type", "application/json; charset=utf-8")
445		w.WriteHeader(status)
446		_ = json.NewEncoder(w).Encode(payload)
447	}
