1	package server
2	
3	import (
4		"io"
5		"mime"
6		"net/http"
7		"sort"
8		"strings"
9	)
10	
11	const (
12		inhibitRulesPath   = "/api/v1/inhibit-rules"
13		inhibitRulesPrefix = inhibitRulesPath + "/"
14	)
15	
16	// inhibitRule is an immutable inhibit-rule document. Replacements swap the
17	// pointer atomically, so readers never observe a half-updated rule.
18	type inhibitRule struct {
19		id            string
20		sourceRuleIDs []string
21		targetRuleIDs []string
22		comment       string
23	}
24	
25	// ---- JSON wire shapes ------------------------------------------------------
26	
27	type inhibitRuleJSON struct {
28		ID            string   `json:"id"`
29		SourceRuleIDs []string `json:"source_rule_ids"`
30		TargetRuleIDs []string `json:"target_rule_ids"`
31		Comment       string   `json:"comment"`
32	}
33	
34	func inhibitRuleWireJSON(r *inhibitRule) inhibitRuleJSON {
35		return inhibitRuleJSON{
36			ID:            r.id,
37			SourceRuleIDs: append([]string(nil), r.sourceRuleIDs...),
38			TargetRuleIDs: append([]string(nil), r.targetRuleIDs...),
39			Comment:       r.comment,
40		}
41	}
42	
43	// ---- request decoding ------------------------------------------------------
44	
45	type rawInhibitRule struct {
46		SourceRuleIDs *[]string `json:"source_rule_ids"`
47		TargetRuleIDs *[]string `json:"target_rule_ids"`
48		Comment       *string   `json:"comment"`
49	}
50	
51	// decodeInhibitRule parses and fully validates an inhibit-rule body. It never
52	// returns a partially validated rule.
53	func decodeInhibitRule(body []byte) (*inhibitRule, bool) {
54		var raw rawInhibitRule
55		if !strictDecode(body, &raw) {
56			return nil, false
57		}
58		if raw.SourceRuleIDs == nil || raw.TargetRuleIDs == nil || raw.Comment == nil {
59			return nil, false
60		}
61	
62		sources, ok := validRuleIDSet(*raw.SourceRuleIDs)
63		if !ok {
64			return nil, false
65		}
66		targets, ok := validRuleIDSet(*raw.TargetRuleIDs)
67		if !ok {
68			return nil, false
69		}
70		for _, id := range sources {
71			if _, crossed := indexOf(targets, id); crossed {
72				return nil, false
73			}
74		}
75	
76		return &inhibitRule{
77			sourceRuleIDs: sources,
78			targetRuleIDs: targets,
79			comment:       *raw.Comment,
80		}, true
81	}
82	
83	// validRuleIDSet checks a non-empty list of unique, syntactically valid rule
84	// identifiers and returns a defensive copy.
85	func validRuleIDSet(ids []string) ([]string, bool) {
86		if len(ids) == 0 {
87			return nil, false
88		}
89		seen := make(map[string]bool, len(ids))
90		for _, id := range ids {
91			if !identPattern.MatchString(id) || seen[id] {
92				return nil, false
93			}
94			seen[id] = true
95		}
96		return append([]string(nil), ids...), true
97	}
98	
99	func indexOf(ids []string, want string) (int, bool) {
100		for i, id := range ids {
101			if id == want {
102				return i, true
103			}
104		}
105		return -1, false
106	}
107	
108	// ---- store operations ------------------------------------------------------
109	
110	func (s *metricStore) putInhibitRule(r *inhibitRule) bool {
111		s.mu.Lock()
112		defer s.mu.Unlock()
113		_, existed := s.inhibitRules[r.id]
114		s.inhibitRules[r.id] = r
115		return !existed
116	}
117	
118	func (s *metricStore) getInhibitRule(id string) (*inhibitRule, bool) {
119		s.mu.RLock()
120		defer s.mu.RUnlock()
121		r, ok := s.inhibitRules[id]
122		return r, ok
123	}
124	
125	func (s *metricStore) deleteInhibitRule(id string) bool {
126		s.mu.Lock()
127		defer s.mu.Unlock()
128		if _, ok := s.inhibitRules[id]; !ok {
129			return false
130		}
131		delete(s.inhibitRules, id)
132		return true
133	}
134	
135	// snapshotInhibitRules returns all inhibit rules sorted by id. Rule objects
136	// are immutable, so the pointers stay safe after the lock is released.
137	func (s *metricStore) snapshotInhibitRules() []*inhibitRule {
138		s.mu.RLock()
139		defer s.mu.RUnlock()
140		out := make([]*inhibitRule, 0, len(s.inhibitRules))
141		for _, r := range s.inhibitRules {
142			out = append(out, r)
143		}
144		sort.Slice(out, func(i, j int) bool { return out[i].id < out[j].id })
145		return out
146	}
147	
148	// ---- HTTP handlers ---------------------------------------------------------
149	
150	func registerInhibitHandlers(mux *http.ServeMux, store *metricStore) {
151		mux.HandleFunc(inhibitRulesPath, func(w http.ResponseWriter, r *http.Request) {
152			if r.Method != http.MethodGet {
153				w.Header().Set("Allow", http.MethodGet)
154				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
155				return
156			}
157			rules := store.snapshotInhibitRules()
158			body := make([]inhibitRuleJSON, 0, len(rules))
159			for _, rule := range rules {
160				body = append(body, inhibitRuleWireJSON(rule))
161			}
162			writeJSON(w, http.StatusOK, map[string]any{"rules": body})
163		})
164	
165		mux.HandleFunc(inhibitRulesPrefix, func(w http.ResponseWriter, r *http.Request) {
166			id := strings.TrimPrefix(r.URL.Path, inhibitRulesPrefix)
167			switch r.Method {
168			case http.MethodGet, http.MethodDelete:
169				// Reads and deletions can only address an existing, syntactically
170				// valid rule id; anything else is simply not found.
171				if id == "" || strings.Contains(id, "/") || !identPattern.MatchString(id) {
172					writeAPIError(w, "inhibit_rule_not_found", http.StatusNotFound)
173					return
174				}
175				if r.Method == http.MethodGet {
176					handleInhibitRuleGet(w, id, store)
177				} else {
178					handleInhibitRuleDelete(w, id, store)
179				}
180			case http.MethodPut:
181				// A structurally nested path is outside this resource subtree;
182				// an identifier-shaped but invalid id is a bad identifier.
183				if id == "" || strings.Contains(id, "/") {
184					writeAPIError(w, "inhibit_rule_not_found", http.StatusNotFound)
185					return
186				}
187				if !identPattern.MatchString(id) {
188					writeAPIError(w, "invalid_inhibit_rule", http.StatusBadRequest)
189					return
190				}
191				handleInhibitRulePut(w, r, id, store)
192			default:
193				w.Header().Set("Allow", "GET, PUT, DELETE")
194				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
195			}
196		})
197	}
198	
199	func handleInhibitRuleGet(w http.ResponseWriter, id string, store *metricStore) {
200		rule, ok := store.getInhibitRule(id)
201		if !ok {
202			writeAPIError(w, "inhibit_rule_not_found", http.StatusNotFound)
203			return
204		}
205		writeJSON(w, http.StatusOK, inhibitRuleWireJSON(rule))
206	}
207	
208	func handleInhibitRulePut(w http.ResponseWriter, r *http.Request, id string, store *metricStore) {
209		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
210		if err != nil || mediaType != "application/json" {
211			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
212			return
213		}
214	
215		body, err := io.ReadAll(r.Body)
216		if err != nil {
217			writeAPIError(w, "invalid_inhibit_rule", http.StatusBadRequest)
218			return
219		}
220	
221		rule, ok := decodeInhibitRule(body)
222		if !ok {
223			writeAPIError(w, "invalid_inhibit_rule", http.StatusBadRequest)
224			return
225		}
226		rule.id = id
227	
228		created := store.putInhibitRule(rule)
229		status := http.StatusOK
230		if created {
231			status = http.StatusCreated
232		}
233		writeJSON(w, status, inhibitRuleWireJSON(rule))
234	}
235	
236	func handleInhibitRuleDelete(w http.ResponseWriter, id string, store *metricStore) {
237		if !store.deleteInhibitRule(id) {
238			writeAPIError(w, "inhibit_rule_not_found", http.StatusNotFound)
239			return
240		}
241		w.WriteHeader(http.StatusNoContent)
242	}

