		t.Fatalf("child = %v", child)
	}
	ids := child["inhibition_ids"].([]any)
	if len(ids) != 2 || ids[0] != "a_inh" || ids[1] != "z_inh" {
		t.Fatalf("child inhibition_ids = %v", ids)
	}

	root := byID["root"]
